{
    .reg .pred %pt, %pk, %pmore, %pr, %pk2;
    .reg .u32 %tx, %ty, %tlin, %bx, %by, %n, %t, %k, %m, %kg, %kk, %ng, %aoff, %boff, %tn, %c, %r, %q, %row, %col, %grow;
    .reg .u64 %ap, %bp, %cp, %sa, %sb, %off, %gaddr, %saddr, %asbase, %bsbase, %rstride, %curo, %nxto, %tmpo;
    .reg .f32 %acc<64>, %av<8>, %bv<8>;
    .shared .align 16 .b8 As[16384];
    .shared .align 16 .b8 Bs[16384];
